package com.bank.orgchart;

import java.util.*;
import java.util.logging.*;

public class OrgChartDemo {
    private static final Logger log = Logger.getLogger("OrgChart");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> employees = List.of(
            new Employee("Rajesh", "Trading"), new Employee("Priya", "Risk"),
            new Employee("Vikram", "Management"), new Employee("Amit", "Settlement"),
            new Employee("Sneha", "Trading"));
        OrgChartService service = new OrgChartService();

        TreeMap<String, List<String>> chart = service.byDepartmentSorted(employees);
        chart.forEach((dept, names) -> log.info(() -> dept + " -> " + names));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    Employee(String name, String department) { this.name = name; this.department = department; }
    String getName() { return name; }
    String getDepartment() { return department; }
}

// ─── Would be in service/OrgChartService.java ───
class OrgChartService {
    // three-arg groupingBy: classifier + TreeMap factory (sorted keys) + downstream
    TreeMap<String, List<String>> byDepartmentSorted(List<Employee> employees) {
        return employees.stream().collect(
            java.util.stream.Collectors.groupingBy(
                Employee::getDepartment,                 // classifier
                TreeMap::new,                            // map factory → sorted keys
                java.util.stream.Collectors.mapping(     // downstream: names only
                    Employee::getName, java.util.stream.Collectors.toList())));
    }
}
